// Appends Nail Structure & Analysis ids 201-215 + Nail Care ids 216-250
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const nsT=`"Nail Structure & Analysis"`, nsTes=`"Estructura y Análisis de Uñas"`, nsPt=`"Nail Structure & Analysis"`, nsPtes=`"Estructura y Análisis de Uñas"`
const ncT=`"Nail Care"`, ncTes=`"Cuidado de Uñas"`, ncPt=`"Nail Care"`, ncPtes=`"Cuidado de Uñas"`

function fmt(q, t, tes, pt, ptes) {
  return `  { id: ${q.id}, topic: ${t}, topic_es: ${tes}, psi_topic: ${pt}, psi_topic_es: ${ptes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const NS = [
  { id: 201, question: "Onychophagy (nail biting) can lead to which nail-related complications relevant to esthetics?", question_es: "La onicofagia (morderse las uñas) puede provocar cuáles complicaciones relacionadas con las uñas relevantes para la estética?", options: ["Damaged nail folds and cuticle, increased risk of paronychia (infection of the nail fold), nail plate irregularities, and introduction of oral bacteria to the periungual area — all of which may affect the safety and outcome of nail services", "No complications — nail biting simply shortens the nail without affecting surrounding tissue", "Only cosmetic concerns — nail biters have no infection risk beyond normal clients", "Onychophagy automatically disqualifies a client from receiving any nail service"], options_es: ["Pliegues ungueales y cutícula dañados, mayor riesgo de paroniquia (infección del pliegue ungueal), irregularidades de la placa ungueal y la introducción de bacterias orales al área periungueal — todo lo cual puede afectar la seguridad y el resultado de los servicios de uñas", "Sin complicaciones — morderse las uñas simplemente acorta la uña sin afectar el tejido circundante", "Solo preocupaciones cosméticas — los que se muerden las uñas no tienen ningún riesgo de infección más allá de los clientes normales", "La onicofagia descalifica automáticamente a un cliente de recibir cualquier servicio de uñas"], correct: 0, explanation: "Chronic nail biting damages the nail plate surface, cuticles, and nail folds. The disrupted cuticle seal introduces oral bacteria (including Streptococcus and Staphylococcus) to the periungual tissues, significantly increasing paronychia risk. Nail biters may also have irregular nail plate surfaces and shortened nail beds that affect service outcomes and technique." },
  { id: 202, question: "Nail psoriasis affects approximately 50% of people with psoriasis and presents in nails as:", question_es: "La psoriasis ungueal afecta aproximadamente al 50% de las personas con psoriasis y se presenta en las uñas como:", options: ["Nail pitting (small depressions on the nail surface), onycholysis (nail separation), oil spots (yellowish discoloration), nail thickening, and crumbling — these changes can mimic fungal infection but are caused by the autoimmune skin condition psoriasis", "Only white spots — nail psoriasis exclusively causes leukonychia", "Darkening of the nail plate to black — melanin overproduction is the primary nail psoriasis sign", "Nail psoriasis causes complete loss of the nail plate — nails fall off and do not regrow"], options_es: ["Picaduras de uñas (pequeñas depresiones en la superficie de la uña), onicólisis (separación de la uña), manchas de aceite (decoloración amarillenta), engrosamiento y desintegración de la uña — estos cambios pueden imitar la infección fúngica pero son causados por la condición cutánea autoinmune psoriasis", "Solo manchas blancas — la psoriasis ungueal causa exclusivamente leuconiquia", "Oscurecimiento de la placa ungueal a negro — la sobreproducción de melanina es el signo principal de la psoriasis ungueal", "La psoriasis ungueal causa la pérdida completa de la placa ungueal — las uñas se caen y no vuelven a crecer"], correct: 0, explanation: "Nail psoriasis manifestations: pitting (multiple small depressions), oil drop/salmon patch (yellowish-pink discoloration under nail), onycholysis (nail separation from nail bed), subungual hyperkeratosis (build-up under nail), Beau's lines, and nail crumbling. It can closely mimic onychomycosis. Clients with active nail psoriasis may receive gentle nail services avoiding the affected areas." },
  { id: 203, question: "A subungual hematoma (blood beneath the nail plate) resulting from trauma during a nail service requires:", question_es: "Un hematoma subungueal (sangre debajo de la placa ungueal) resultante de un traumatismo durante un servicio de uñas requiere:", options: ["Stopping the nail service, applying pressure if there is any bleeding, informing the client of what occurred, and recommending medical evaluation if the hematoma is large or painful — a large hematoma may require physician drainage to prevent nail loss", "Immediately drilling a hole in the nail plate to relieve pressure — estheticians should perform this procedure", "Applying nail polish to cover the discoloration and continuing the service", "No action — subungual hematomas always resolve on their own within 24 hours without any concern"], options_es: ["Detener el servicio de uñas, aplicar presión si hay sangrado, informar al cliente de lo ocurrido y recomendar evaluación médica si el hematoma es grande o doloroso — un hematoma grande puede requerir drenaje médico para evitar la pérdida de la uña", "Inmediatamente perforar un agujero en la placa ungueal para aliviar la presión — los esteticistas deben realizar este procedimiento", "Aplicar esmalte de uñas para cubrir la decoloración y continuar el servicio", "Sin acción — los hematomas subungueales siempre se resuelven solos dentro de las 24 horas sin ninguna preocupación"], correct: 0, explanation: "A subungual hematoma (blood under the nail from trauma) can be painful. The correct esthetics response: stop the service, manage any external bleeding, document the incident, and advise the client to seek medical care if the hematoma is large (risk of nail loss), extremely painful, or accompanied by possible nail bed injury. Trephination (drilling) is a medical procedure outside esthetics scope." },
  { id: 204, question: "Melanonychia (dark, longitudinal pigmented bands in the nail) is significant in an esthetics assessment because:", question_es: "La melanoniquia (bandas pigmentadas oscuras y longitudinales en la uña) es significativa en una evaluación de estética porque:", options: ["While melanonychia can be benign (common in darker skin tones, from trauma, medications, or race-related pigmentation), it can also indicate subungual melanoma — a potentially serious malignancy; any new, widening, or changing dark nail band should be referred for medical evaluation", "Dark nail bands are always benign cosmetic pigmentation — no medical concern is warranted", "Melanonychia is exclusively caused by nail polish staining from dark-colored polishes", "Dark nail bands indicate iron deficiency and improve with iron supplementation without medical evaluation"], options_es: ["Aunque la melanoniquia puede ser benigna (común en tonos de piel más oscuros, por traumatismo, medicamentos o pigmentación relacionada con la raza), también puede indicar melanoma subungueal — una malignidad potencialmente grave; cualquier banda ungueal oscura nueva, que se ensancha o cambia debe referirse para evaluación médica", "Las bandas ungueales oscuras son siempre pigmentación cosmética benigna — no se justifica ninguna preocupación médica", "La melanoniquia es causada exclusivamente por la tinción de esmalte de uñas de esmaltes de color oscuro", "Las bandas ungueales oscuras indican deficiencia de hierro y mejoran con la suplementación de hierro sin evaluación médica"], correct: 0, explanation: "Longitudinal melanonychia is common in people with darker skin types and can be benign. However, the 'ABCDEF' rule for nail melanoma includes: Age (peak 5th–7th decade), Band (brown-black, breadth >3mm, border irregular), Change (rapid), Digit (thumb, index, big toe), Extension (to nail fold = Hutchinson sign), and Family/personal history of melanoma. New or changing dark nail bands warrant dermatology referral." },
  { id: 205, question: "Onychogryposis (ram's horn nail) is characterized by:", question_es: "La onicogrifosis (uña en cuerno de carnero) se caracteriza por:", options: ["Severe thickening and abnormal curvature of the nail plate that may twist and curl like a ram's horn — most common in elderly patients and on the great toenail; often associated with neglect, repeated trauma, poor circulation, or fungal infection; may require podiatric care", "Thinning and fragility of the nail plate to the point of near-transparency", "A condition where the nail grows into the lateral nail fold (ingrown nail)", "Horizontal white banding across the nail plate from systemic toxin exposure"], options_es: ["Engrosamiento severo y curvatura anormal de la placa ungueal que puede torcerse y rizarse como un cuerno de carnero — más común en pacientes de edad avanzada y en la uña del dedo gordo del pie; a menudo asociado con negligencia, traumatismo repetido, mala circulación o infección fúngica; puede requerir atención podológica", "Adelgazamiento y fragilidad de la placa ungueal hasta el punto de casi transparencia", "Una condición donde la uña crece hacia el pliegue ungueal lateral (uña encarnada)", "Bandas blancas horizontales a través de la placa ungueal por exposición a toxinas sistémicas"], correct: 0, explanation: "Onychogryposis is extreme nail hypertrophy with spiral twisting — the nail can resemble a ram's horn. It is most common in the elderly and on the great toenail. Causes include years of mechanical trauma, neglect (nail not trimmed), impaired circulation, and fungal infection. Management typically requires podiatric intervention; esthetics nail services are limited given the nail's severity." },
  { id: 206, question: "Pterygium unguis (dorsal pterygium) occurs when:", question_es: "El pterigión ungueal (pterigión dorsal) ocurre cuando:", options: ["The proximal nail fold grows forward over the nail plate, gradually covering and eventually destroying the nail — it can result from lichen planus, repeated trauma to the matrix, or surgical scarring; it is not the same as simple cuticle overgrowth", "The free edge of the nail grows backward toward the matrix", "The hyponychium overgrows and separates the nail plate from the nail bed", "Normal cuticle tissue thickens from repeated manicure services"], options_es: ["El pliegue ungueal proximal crece hacia adelante sobre la placa ungueal, cubriéndola gradualmente y finalmente destruyéndola — puede resultar de liquen plano, traumatismo repetido en la matriz o cicatrización quirúrgica; no es lo mismo que el simple sobrecrecimiento de la cutícula", "El borde libre de la uña crece hacia atrás en dirección a la matriz", "El hiponiquio crece excesivamente y separa la placa ungueal del lecho ungueal", "El tejido normal de la cutícula se engrosa por los servicios repetidos de manicura"], correct: 0, explanation: "Pterygium unguis is a permanent scarring condition where skin tissue grows forward onto the nail plate, eventually fusing with it and potentially destroying the nail matrix. It differs from simple cuticle overgrowth — pterygium cannot be pushed back. The most common cause is lichen planus. This is a medical condition requiring physician management, not an esthetics service." },
  { id: 207, question: "Splinter hemorrhages under the nail plate appear as:", question_es: "Las hemorragias en astilla debajo de la placa ungueal aparecen como:", options: ["Thin, dark red-brown lines (like splinters) running longitudinally under the nail — they may result from minor trauma, but multiple splinter hemorrhages on multiple nails can indicate systemic conditions such as infective endocarditis, vasculitis, or psoriasis — warranting medical referral", "White transverse lines running horizontally across the nail plate (Mees' lines)", "Yellow-orange discoloration of the entire nail plate", "Circular dark spots in the center of the nail plate"], options_es: ["Líneas finas de color rojo oscuro a marrón (como astillas) que corren longitudinalmente debajo de la uña — pueden resultar de traumatismo menor, pero múltiples hemorragias en astilla en múltiples uñas pueden indicar condiciones sistémicas como endocarditis infecciosa, vasculitis o psoriasis — lo que justifica derivación médica", "Líneas blancas transversales que corren horizontalmente a través de la placa ungueal (líneas de Mees)", "Decoloración amarillo-naranja de toda la placa ungueal", "Manchas oscuras circulares en el centro de la placa ungueal"], correct: 0, explanation: "Splinter hemorrhages are tiny capillary bleeds from the nail bed's longitudinal vessels, appearing as dark streaks under the nail. Isolated splinter hemorrhages from minor nail trauma are benign. Multiple splinter hemorrhages across multiple digits may signal systemic disease (endocarditis, vasculitis, trichinosis) and require medical referral. This demonstrates why nail assessment is a health screening opportunity." },
  { id: 208, question: "Terry's nails (mostly white nails with a narrow pink band at the free edge) are associated with:", question_es: "Las uñas de Terry (uñas mayormente blancas con una estrecha banda rosada en el borde libre) están asociadas con:", options: ["Systemic conditions including liver cirrhosis, congestive heart failure, diabetes mellitus, and kidney failure — when seen in a client, the esthetician should recommend medical evaluation if not already diagnosed", "Normal aging in adults over 60 — Terry's nails are a benign age-related change", "Excessive application of white-tinted base coat — the product pigment penetrates the nail plate", "Iron deficiency — supplementation resolves the appearance within weeks"], options_es: ["Condiciones sistémicas que incluyen cirrosis hepática, insuficiencia cardíaca congestiva, diabetes mellitus e insuficiencia renal — cuando se observan en un cliente, el esteticista debe recomendar evaluación médica si aún no está diagnosticada", "Envejecimiento normal en adultos mayores de 60 años — las uñas de Terry son un cambio benigno relacionado con la edad", "Aplicación excesiva de base coat con pigmento blanco — el pigmento del producto penetra la placa ungueal", "Deficiencia de hierro — la suplementación resuelve la apariencia en semanas"], correct: 0, explanation: "Terry's nails present as nails that are whitish for most of their length with a narrow 2–3mm pink distal band. This pattern is associated with several systemic conditions: hepatic cirrhosis (most classic), congestive heart failure, type 2 diabetes, and renal failure. While more common with aging, their presence in a client warrants inquiry about systemic health status." },
  { id: 209, question: "Nail clubbing (increased curvature of the nail plate with a widened, rounded finger tip) is associated with:", question_es: "El dedos en palillo de tambor (mayor curvatura de la placa ungueal con una punta del dedo más ancha y redondeada) está asociado con:", options: ["Chronic oxygen deficiency from conditions such as heart disease, chronic lung disease (emphysema, cystic fibrosis), liver disease, or inflammatory bowel disease — nail clubbing observed during a service warrants inquiry and medical referral if unexplained", "Excessive nail buffing — mechanical trauma causes the nail to curve and the fingertip to enlarge", "Normal nail variation — clubbing is a harmless anatomical variant with no health implications", "Nail fungal infection — onychomycosis causes the nail plate to enlarge and curve over time"], options_es: ["Deficiencia crónica de oxígeno por condiciones como enfermedades cardíacas, enfermedades pulmonares crónicas (enfisema, fibrosis quística), enfermedades hepáticas o enfermedades inflamatorias intestinales — la clubbing ungueal observada durante un servicio justifica una consulta y derivación médica si no se explica", "Limado excesivo de uñas — el traumatismo mecánico hace que la uña se curve y la punta del dedo se agrande", "Variación normal de las uñas — la clubbing es una variante anatómica inofensiva sin implicaciones para la salud", "Infección fúngica de las uñas — la onicomicosis hace que la placa ungueal se agrande y se curve con el tiempo"], correct: 0, explanation: "Nail clubbing is characterized by: increased distal phalanx diameter, loss of normal Lovibond angle (<180° becomes ≥180°), nail plate hyperconvexity, and 'spongy' feel when pressing the nail base. It results from chronic hypoxia (low oxygen) or inflammatory mediators. Causes include COPD, congenital heart disease, hepatic cirrhosis, and GI disorders. It is a significant systemic health marker." },
  { id: 210, question: "Mees' lines (also called Aldrich-Mees' lines) on the nail plate are:", question_es: "Las líneas de Mees (también llamadas líneas de Aldrich-Mees) en la placa ungueal son:", options: ["White transverse bands (true leukonychia) running horizontally across the full width of the nail plate, associated with arsenic or thallium poisoning, renal failure, or Hodgkin's disease — they are distinct from leukonychia striata from nail trauma", "Longitudinal dark bands associated with subungual melanoma", "Transverse depressions (not color changes) from nail growth arrest during illness", "Normal age-related striations that appear after age 50"], options_es: ["Bandas blancas transversales (leuconiquia verdadera) que corren horizontalmente a través de todo el ancho de la placa ungueal, asociadas con envenenamiento por arsénico o talio, insuficiencia renal o enfermedad de Hodgkin — son distintas de la leuconiquia estriada por traumatismo ungueal", "Bandas oscuras longitudinales asociadas con melanoma subungueal", "Depresiones transversales (no cambios de color) del arresto del crecimiento ungueal durante la enfermedad", "Estrías relacionadas con el envejecimiento que aparecen después de los 50 años"], correct: 0, explanation: "Mees' lines are true leukonychia (white color in the nail plate substance) running completely across the nail width. They are most classically associated with arsenic poisoning but can appear with other heavy metal poisonings, renal failure, and Hodgkin's lymphoma. Their position on the nail can help date the causative event. They differ from Beau's lines (transverse depressions, not color changes)." },
  { id: 211, question: "An agnail (hangnail) is:", question_es: "Un agnail (padrastro) es:", options: ["A small, torn piece of cuticle or nail wall skin adjacent to the nail plate — it should be carefully trimmed with clean cuticle nippers (never torn) to prevent tearing further into the living skin and creating an entry point for infection", "A small nail fragment that has grown embedded in the nail fold, requiring surgical removal", "A fungal infection of the nail fold that requires antifungal treatment", "A benign cyst under the nail fold, unrelated to cuticle or nail care"], options_es: ["Un pequeño trozo de cutícula desgarrado o piel de la pared ungueal adyacente a la placa ungueal — debe recortarse cuidadosamente con cortinas de cutícula limpias (nunca arrancado) para evitar desgarrarse más en la piel viva y crear un punto de entrada para la infección", "Un pequeño fragmento ungueal que ha crecido incrustado en el pliegue ungueal, que requiere extirpación quirúrgica", "Una infección fúngica del pliegue ungueal que requiere tratamiento antimicótico", "Un quiste benigno debajo del pliegue ungueal, sin relación con la cutícula o el cuidado de las uñas"], correct: 0, explanation: "An agnail (hangnail) is a torn or ragged strip of skin adjacent to the nail plate. The correct technique: use sharp, clean cuticle nippers to cleanly trim the hangnail flush with the skin — never pull or tear, which would extend the tear into living, vascularized tissue, increasing pain and infection risk. After trimming, apply a light antiseptic and cuticle conditioner." },
  { id: 212, question: "Onychoptosis (nail shedding) — loss of the nail plate — can result from:", question_es: "La onicoptosis (pérdida de la uña) — pérdida de la placa ungueal — puede resultar de:", options: ["Severe acute illness with high fever, syphilis, drug reactions (particularly Stevens-Johnson syndrome), severe local trauma, or very severe onychomycosis — the nail is shed when the matrix is severely disrupted and the nail plate separates completely from its underlying structures", "Excessive nail buffing during manicure services — buffing always eventually causes nail loss", "Normal nail growth cycle — nails shed and regrow seasonally like deciduous leaves", "Application of acrylic nail products — acrylics always cause natural nail loss beneath them"], options_es: ["Enfermedad aguda grave con fiebre alta, sífilis, reacciones a medicamentos (particularmente el síndrome de Stevens-Johnson), traumatismo local severo o onicomicosis muy severa — la uña se pierde cuando la matriz está gravemente perturbada y la placa ungueal se separa completamente de sus estructuras subyacentes", "Limado excesivo de uñas durante los servicios de manicura — el limado siempre eventualmente causa la pérdida de la uña", "Ciclo normal de crecimiento de las uñas — las uñas se desprenden y vuelven a crecer estacionalmente como las hojas caducas", "Aplicación de productos de uñas de acrílico — los acrílicos siempre causan la pérdida de la uña natural debajo de ellos"], correct: 0, explanation: "Onychoptosis (defluvium unguium) refers to periodic shedding of all or part of the nail plate. Causes include: very high fever, syphilis, drug reactions, severe trauma, or severe onychomycosis that destroys the matrix. A client who has experienced recent nail loss should be referred for medical evaluation before any nail service is attempted on the affected digit." },
  { id: 213, question: "When performing a nail assessment, 'pitting' of the nail surface (small, ice-pick-like depressions) most commonly indicates:", question_es: "Al realizar una evaluación de uñas, las 'picaduras' de la superficie de la uña (pequeñas depresiones parecidas a pinchazo de hielo) más comúnmente indican:", options: ["Psoriasis — nail pitting is one of the most common nail manifestations of psoriasis, resulting from abnormal keratinization in the matrix; it can also occur in alopecia areata and reactive arthritis (formerly Reiter's syndrome)", "Iron deficiency — pitting indicates insufficient iron in the nail's keratin matrix", "Excessive exposure to acetone-based nail polish remover — the solvent pits the nail surface", "Normal variant — random pitting is common in healthy nails without any systemic cause"], options_es: ["Psoriasis — las picaduras de uñas son una de las manifestaciones ungueales más comunes de la psoriasis, resultando de la queratinización anormal en la matriz; también puede ocurrir en la alopecia areata y la artritis reactiva (anteriormente síndrome de Reiter)", "Deficiencia de hierro — las picaduras indican hierro insuficiente en la matriz de queratina de la uña", "Exposición excesiva al removedor de esmalte de uñas a base de acetona — el solvente pica la superficie de la uña", "Variante normal — las picaduras aleatorias son comunes en uñas sanas sin ninguna causa sistémica"], correct: 0, explanation: "Nail pitting (punctate leukonychia of the nail surface) results from small foci of parakeratotic cells in the nail plate produced by the nail matrix. It is a hallmark of psoriasis (present in up to 80% of psoriatic patients with nail involvement). It also occurs in alopecia areata and reactive arthritis. Multiple, deep pits in multiple digits should prompt medical referral." },
  { id: 214, question: "The free edge of the nail is defined as:", question_es: "El borde libre de la uña se define como:", options: ["The portion of the nail plate that extends beyond the tip of the finger (beyond the hyponychium) — this is the part of the nail that is shaped, trimmed, and polished during nail care services", "The proximal edge of the nail plate at the cuticle", "The lateral edges of the nail plate on either side", "The lower edge of the nail plate that attaches to the nail bed"], options_es: ["La porción de la placa ungueal que se extiende más allá de la punta del dedo (más allá del hiponiquio) — esta es la parte de la uña que se da forma, se recorta y se pule durante los servicios de cuidado de uñas", "El borde proximal de la placa ungueal en la cutícula", "Los bordes laterales de la placa ungueal a cada lado", "El borde inferior de la placa ungueal que se une al lecho ungueal"], correct: 0, explanation: "The free edge is the distal portion of the nail plate that has grown past the fingertip and is not attached to the nail bed. It is the primary area manipulated during nail services (filing, shaping, tip application, and polishing). The length and shape of the free edge determines the nail's appearance. Its thickness and condition indicate nail health." },
  { id: 215, question: "The nail plate's natural color in a healthy adult is:", question_es: "El color natural de la placa ungueal en un adulto sano es:", options: ["Translucent with a pinkish hue — the pink color comes from the underlying nail bed's rich capillary blood supply visible through the transparent nail plate, and it appears white at the free edge where the nail detaches from the nail bed", "Completely opaque white — healthy nails are chalk-white in color", "Pale yellow — the natural keratin pigment of nails is a light yellow color", "Clear and colorless with no visible hue — healthy nails have no visible color"], options_es: ["Translúcido con una tonalidad rosada — el color rosado proviene del rico suministro sanguíneo capilar del lecho ungueal subyacente visible a través de la placa ungueal transparente, y parece blanco en el borde libre donde la uña se desprende del lecho ungueal", "Completamente blanco opaco — las uñas sanas son de color blanco tiza", "Amarillo pálido — el pigmento natural de queratina de las uñas es de color amarillo claro", "Claro e incoloro sin ninguna tonalidad visible — las uñas sanas no tienen color visible"], correct: 0, explanation: "Healthy nail plates are naturally translucent/transparent. Their pink appearance comes from the nail bed's dermal blood supply showing through the plate. The free edge appears white because there is no nail bed beneath it to provide the pink color. Deviations from translucent pink (yellowing, browning, whitening, darkening) may indicate pathology." },
]

const NC = [
  { id: 216, question: "The correct direction for filing natural nails is:", question_es: "La dirección correcta para limar las uñas naturales es:", options: ["File in one direction only — moving from the outer corner toward the center of the nail tip — to avoid weakening and splitting the nail plate; a back-and-forth sawing motion generates heat and friction that can cause nail delamination and breakage", "Always file in a back-and-forth sawing motion for fastest shaping results", "File from the center outward toward each corner on both sides simultaneously", "Always file from the center toward the tip only — never filing from the side edges"], options_es: ["Limar en una sola dirección — moviéndose desde la esquina exterior hacia el centro de la punta de la uña — para evitar debilitar y partir la placa ungueal; un movimiento de sierra de adelante hacia atrás genera calor y fricción que puede causar delaminación y rotura de la uña", "Siempre limar con un movimiento de sierra de adelante hacia atrás para obtener resultados de formado más rápidos", "Limar desde el centro hacia afuera hacia cada esquina en ambos lados simultáneamente", "Siempre limar desde el centro hacia la punta solamente — nunca limando desde los bordes laterales"], correct: 0, explanation: "Filing in one direction (from corner to center) prevents the sideways stress that causes nail plate delamination and splitting. Back-and-forth filing creates microscopic damage in the nail's keratin layers and heat that weakens the nail tip. This unidirectional technique is especially important for natural nails with any brittleness or layering tendency." },
  { id: 217, question: "Nail file grit numbers indicate:", question_es: "Los números de grano de las limas de uñas indican:", options: ["The coarseness of the abrasive surface — lower grit numbers (80–100) are coarser and remove more material quickly (used for shaping artificial enhancements); higher grit numbers (180–240+) are finer and used for natural nail shaping and smoothing", "The length of the nail file in millimeters", "The number of times the file can be safely used before disposal", "The percentage of synthetic versus natural abrasive material in the file"], options_es: ["La rugosidad de la superficie abrasiva — los números de grano más bajos (80–100) son más ásperos y eliminan más material rápidamente (usados para dar forma a mejoras artificiales); los números de grano más altos (180–240+) son más finos y se usan para dar forma y alisar las uñas naturales", "La longitud de la lima de uñas en milímetros", "El número de veces que la lima puede usarse de forma segura antes de desecharla", "El porcentaje de material abrasivo sintético versus natural en la lima"], correct: 0, explanation: "Grit refers to the size of abrasive particles on the file surface. Low grit (coarse, 80–100) removes nail material rapidly — appropriate for shaping thick acrylics or gel enhancements, but too aggressive for natural nails. Medium grit (150–180) for natural nail shaping. Fine grit (240+) for finishing and smoothing. Using too coarse a grit on natural nails causes excessive thinning and heat generation." },
  { id: 218, question: "The five standard nail shapes that an esthetician should be familiar with are:", question_es: "Las cinco formas estándar de uñas que un esteticista debe conocer son:", options: ["Square (flat tip with sharp corners), squoval (square with slightly rounded corners), oval (filed to a gentle oval at the tip), round (rounded tip following the finger's shape), and almond (tapered to a soft point) — each flatters different finger shapes and lengths", "Triangle, hexagon, star, circle, and diamond", "Sharp, blunt, beveled, curved, and straight", "French, gel, acrylic, dip, and natural"], options_es: ["Cuadrada (punta plana con esquinas afiladas), cuadrada ovalada (cuadrada con esquinas ligeramente redondeadas), ovalada (limada a un óvalo suave en la punta), redonda (punta redondeada que sigue la forma del dedo) y almendra (afilada a una punta suave) — cada una favorece diferentes formas y longitudes de dedos", "Triángulo, hexágono, estrella, círculo y diamante", "Afilada, sin punta, biselada, curvada y recta", "Francesa, gel, acrílico, sumergida y natural"], correct: 0, explanation: "The five classic nail shapes: Square (flat, 90° corners — strong, suitable for most lengths), Squoval (rounded square corners — most popular, balances strength and aesthetics), Oval (tapered sides, oval tip — elongates fingers), Round (follows fingertip contour — classic, low-maintenance), Almond (tapered sides to a soft peak — elegant but weaker). Stiletto and coffin (ballerina) are modern extensions of these shapes." },
  { id: 219, question: "The primary purpose of a nail base coat is:", question_es: "El propósito principal de una base coat (base) para uñas es:", options: ["To create a smooth, adhesive layer between the natural nail and nail polish — it helps the color adhere better (reducing chipping), may contain ingredients that prevent nail staining from pigmented polishes, and some formulations condition the nail plate", "To provide the main color and coverage in a manicure — base coat is the first colored layer", "To seal and protect the finish of the manicure after color application", "To act as a primer that softens the nail plate for better product absorption"], options_es: ["Crear una capa suave y adhesiva entre la uña natural y el esmalte de uñas — ayuda a que el color se adhiera mejor (reduciendo el astillamiento), puede contener ingredientes que eviten el manchado de uñas de esmaltes pigmentados y algunas formulaciones acondicionan la placa ungueal", "Proporcionar el color principal y la cobertura en una manicura — el base coat es la primera capa de color", "Sellar y proteger el acabado de la manicura después de la aplicación del color", "Actuar como imprimante que suaviza la placa ungueal para una mejor absorción del producto"], correct: 0, explanation: "Base coat serves multiple functions: (1) adhesion promoter — creates a bonding layer between nail plate and polish, (2) stain prevention — forms a barrier that prevents dark pigments from penetrating and yellowing the nail, (3) nail conditioner — some formulas contain hardeners, hydrators, or strengtheners. A separate base coat always improves manicure longevity compared to direct color application." },
  { id: 220, question: "A top coat applied as the final step in a nail polish manicure:", question_es: "Un top coat aplicado como paso final en una manicura con esmalte de uñas:", options: ["Seals the nail polish layers from chipping and peeling, adds shine (or matte finish in matte top coats), hardens the surface for increased durability, and helps the color layers dry faster when quick-dry formulas are used", "Removes excess nail polish from the skin around the nail after application", "Provides additional color pigment to enhance the depth of the polish", "Acts as the adhesive that bonds the nail tip to the natural nail plate in tip application"], options_es: ["Sella las capas de esmalte de uñas contra el astillamiento y el pelado, añade brillo (o acabado mate en los top coats mate), endurece la superficie para mayor durabilidad y ayuda a que las capas de color se sequen más rápido cuando se usan fórmulas de secado rápido", "Elimina el exceso de esmalte de uñas de la piel alrededor de la uña después de la aplicación", "Proporciona pigmento de color adicional para mejorar la profundidad del esmalte", "Actúa como adhesivo que une la punta de la uña a la placa ungueal natural en la aplicación de puntas"], correct: 0, explanation: "Top coat is the final protective layer in a manicure. Functions: (1) seal and protect the color layers from chipping, (2) add gloss, shine, or a matte finish depending on formulation, (3) harden the surface layer, (4) speed drying (quick-dry top coats). Applying top coat to the free edge (wrapping the tip) helps prevent tip chipping significantly." },
  { id: 221, question: "Acetone-based nail polish remover compared to non-acetone remover:", question_es: "El removedor de esmalte de uñas a base de acetona en comparación con el removedor sin acetona:", options: ["Acetone is more effective and faster at dissolving nail polish (including gel and glitter polishes) but is more drying to the nail plate and surrounding skin; non-acetone removers (using ethyl acetate, isopropyl alcohol) are gentler but require more effort to remove resistant polishes", "Non-acetone is always more effective than acetone — it dissolves polish faster without any drawbacks", "Acetone and non-acetone removers have identical effects on the nail — the choice is purely based on personal preference", "Acetone remover is only for toenails — fingernail polish requires non-acetone removal"], options_es: ["La acetona es más efectiva y rápida para disolver el esmalte de uñas (incluidos los esmaltes de gel y con brillantina) pero es más desecante para la placa ungueal y la piel circundante; los removedores sin acetona (que usan acetato de etilo, alcohol isopropílico) son más suaves pero requieren más esfuerzo para eliminar los esmaltes resistentes", "El removedor sin acetona siempre es más efectivo que la acetona — disuelve el esmalte más rápido sin ningún inconveniente", "Los removedores de acetona y sin acetona tienen efectos idénticos en la uña — la elección se basa únicamente en la preferencia personal", "El removedor de acetona es solo para las uñas de los pies — el esmalte de las uñas de los dedos requiere remoción sin acetona"], correct: 0, explanation: "Acetone dissolves nail lacquer rapidly and is essential for removing gel polish, glitter, or dark pigmented polishes. It's a strong solvent that temporarily dehydrates the nail plate and can dry the cuticle with repeated use. Non-acetone removers (ethyl acetate, butyl acetate, isopropyl alcohol-based) are gentler but work more slowly and may be ineffective on gel products." },
  { id: 222, question: "Proper cuticle care during a manicure service involves:", question_es: "El cuidado adecuado de la cutícula durante un servicio de manicura implica:", options: ["Softening the cuticle with cuticle remover or warm water, gently pushing back the cuticle with an orangewood stick or rubber-tipped pusher (not metal on the nail surface), and carefully trimming only dead, loose cuticle skin — never cutting living cuticle tissue that serves as a protective seal", "Aggressively cutting all visible cuticle tissue to expose as much nail plate as possible for maximum nail visual length", "Soaking in bleach solution to fully dissolve and remove all cuticle tissue in one step", "Leaving all cuticle tissue intact and untouched — cuticle care is not a standard part of manicure service"], options_es: ["Suavizar la cutícula con removedor de cutícula o agua tibia, empujar suavemente la cutícula hacia atrás con un palito de naranja o empujador de punta de goma (no metal en la superficie de la uña) y recortar cuidadosamente solo la piel de la cutícula muerta y suelta — nunca cortar el tejido de la cutícula vivo que sirve como sello protector", "Cortar agresivamente todo el tejido de la cutícula visible para exponer la mayor cantidad posible de placa ungueal para la máxima longitud visual de la uña", "Remojar en solución de lejía para disolver y eliminar completamente todo el tejido de la cutícula en un solo paso", "Dejar todo el tejido de la cutícula intacto y sin tocar — el cuidado de la cutícula no es una parte estándar del servicio de manicura"], correct: 0, explanation: "Proper cuticle care: soften with cuticle remover cream (which contains keratin-dissolving chemicals like sodium or potassium hydroxide) or warm water, gently push back with non-metal tool, trim only non-living tissue (dead skin tags). The living cuticle seal must be preserved — cutting living cuticle: (1) removes the infection barrier, (2) increases paronychia risk, (3) causes the cuticle to grow back thicker." },
  { id: 223, question: "A paraffin hand treatment in a manicure service provides benefits including:", question_es: "Un tratamiento de parafina para manos en un servicio de manicura proporciona beneficios que incluyen:", options: ["Deep moisturization — heat from the paraffin opens pores and drives moisture into the skin; the occlusive wax layer traps heat and prevents water evaporation, providing intense hydration to dry, cracked, or arthritic hands", "Permanent skin lightening from the paraffin's bleaching chemical components", "Exfoliation — paraffin physically removes dead skin cells when peeled off", "UV protection — the wax layer prevents sun exposure to the hands during and after the treatment"], options_es: ["Hidratación profunda — el calor de la parafina abre los poros y lleva la humedad a la piel; la capa de cera oclusiva atrapa el calor y previene la evaporación del agua, proporcionando hidratación intensa a las manos secas, agrietadas o artríticas", "Aclarado permanente de la piel de los componentes químicos blanqueadores de la parafina", "Exfoliación — la parafina elimina físicamente las células muertas de la piel cuando se pela", "Protección UV — la capa de cera evita la exposición solar a las manos durante y después del tratamiento"], correct: 0, explanation: "Paraffin treatments use thermotherapy (heat) plus occlusion. Benefits: intense moisturization (the occlusive wax locks in moisture and emollient products applied before dipping), temporary relief of arthritis discomfort from gentle heat, improved circulation to the hands, and softening of dry, callused skin. Paraffin wax is single-use per client (sanitation) and contraindicated for open wounds, infections, or heat-sensitive conditions." },
  { id: 224, question: "The correct technique for applying nail polish to achieve an even, smooth coat is:", question_es: "La técnica correcta para aplicar esmalte de uñas y lograr una capa uniforme y suave es:", options: ["Load the brush with a small amount of polish, wipe one side on the neck of the bottle, place the brush 1/8 inch from the cuticle, apply a thin stripe down the center, then stroke each side — applying thin coats rather than one thick coat prevents bubbling and peeling", "Apply one very thick coat of polish for maximum color payoff in minimal time", "Apply polish directly from the bottle without wiping the brush — brush loading determines coat thickness", "Paint from the free edge back toward the cuticle for best cuticle coverage"], options_es: ["Cargar el pincel con una pequeña cantidad de esmalte, limpiar un lado en el cuello de la botella, colocar el pincel a 1/8 de pulgada de la cutícula, aplicar una franja delgada hacia abajo por el centro, luego hacer un trazo en cada lado — aplicar capas delgadas en lugar de una capa gruesa evita burbujas y pelado", "Aplicar una capa muy gruesa de esmalte para el máximo rendimiento de color en el mínimo tiempo", "Aplicar el esmalte directamente de la botella sin limpiar el pincel — la carga del pincel determina el grosor de la capa", "Pintar desde el borde libre hacia atrás hacia la cutícula para una mejor cobertura de la cutícula"], correct: 0, explanation: "Polish application technique: (1) remove excess polish from one side of the brush on bottle neck, (2) place brush near (not on) the cuticle, (3) center stroke first (not touching cuticle), (4) side strokes. Thin coats dry faster, adhere better, and resist peeling/bubbling. Multiple thin coats build color better than one thick coat. Wrap the free edge to prevent tip chipping." },
  { id: 225, question: "During a manicure, the sequence of steps in the correct order is:", question_es: "Durante una manicura, la secuencia de pasos en el orden correcto es:", options: ["Remove old polish → shape nails → soak/soften cuticles → apply cuticle remover → push back and trim cuticles → cleanse the nail plate → apply base coat → apply color coats → apply top coat", "Apply base coat → remove old polish → shape nails → apply color → soak in water", "Soak nails first → remove old polish → apply color → shape nails → apply top coat", "Shape nails → apply color → soak → remove old polish → apply base coat"], options_es: ["Eliminar el esmalte viejo → dar forma a las uñas → remojar/suavizar las cutículas → aplicar removedor de cutícula → empujar hacia atrás y recortar las cutículas → limpiar la placa ungueal → aplicar base coat → aplicar capas de color → aplicar top coat", "Aplicar base coat → eliminar el esmalte viejo → dar forma a las uñas → aplicar color → remojar en agua", "Remojar las uñas primero → eliminar el esmalte viejo → aplicar color → dar forma a las uñas → aplicar base coat", "Dar forma a las uñas → aplicar color → remojar → eliminar el esmalte viejo → aplicar base coat"], correct: 0, explanation: "Correct manicure sequence: (1) Polish removal, (2) nail shaping (file before soaking — wet nails are soft and prone to tearing), (3) soak/soften cuticles, (4) cuticle care (push, trim), (5) nail plate cleanse/dehydrate (remove oils for polish adhesion), (6) base coat, (7) color coats (usually 2), (8) top coat. Filing BEFORE soaking is key — wet nails file unevenly and can split." },
  { id: 226, question: "A hand massage performed during a manicure service provides which documented benefit?", question_es: "Un masaje de manos realizado durante un servicio de manicura proporciona cuál beneficio documentado?", options: ["Improved local blood circulation, relaxation of hand muscles and tendons (beneficial for clients with repetitive strain), enhanced product penetration when massage is performed with a lotion or oil, and client comfort and stress reduction", "Permanent elongation of the fingers from stretching during massage", "Removal of dead skin cells from the palm through friction", "Prevention of nail fungal infections — massage disrupts fungal colonization of the nail folds"], options_es: ["Mejora de la circulación sanguínea local, relajación de los músculos y tendones de la mano (beneficioso para clientes con lesiones por esfuerzo repetitivo), mayor penetración del producto cuando el masaje se realiza con una loción o aceite, y comodidad del cliente y reducción del estrés", "Elongación permanente de los dedos por estiramiento durante el masaje", "Eliminación de células muertas de la piel de la palma a través de la fricción", "Prevención de las infecciones fúngicas de las uñas — el masaje interrumpe la colonización fúngica de los pliegues ungueales"], correct: 0, explanation: "Hand massage during manicure: (1) improves local circulation (benefits nail growth and skin health), (2) relaxes overworked hand muscles and reduces tension in the tendons and ligaments, (3) enhances absorption of applied lotion or oil, (4) provides relaxation and stress relief. Massage is performed before polish application to avoid disrupting the nail surface." },
  { id: 227, question: "A ridge-filling base coat differs from a regular base coat in that it:", question_es: "Una base coat rellenadora de estrías difiere de una base coat regular en que:", options: ["Contains additional fillers (often titanium dioxide or similar opacifying agents) that fill in nail ridges and create a smoother surface for color application — beneficial for nails with pronounced longitudinal ridging from aging or nutritional factors", "Is applied only at the free edge, not on the entire nail surface", "Contains a higher concentration of color pigment to disguise the nail's natural color", "Must be used only on artificial nail enhancements, not on natural nails"], options_es: ["Contiene rellenos adicionales (a menudo dióxido de titanio o agentes opacificadores similares) que rellenan los estrías de las uñas y crean una superficie más suave para la aplicación del color — beneficioso para las uñas con estrías longitudinales pronunciadas por el envejecimiento o factores nutricionales", "Se aplica solo en el borde libre, no en toda la superficie de la uña", "Contiene una concentración más alta de pigmento de color para disimular el color natural de la uña", "Solo debe usarse en mejoras de uñas artificiales, no en uñas naturales"], correct: 0, explanation: "Ridge-filling base coats contain opaque fillers that fill in the grooves of ridged nail surfaces. This creates a smoother canvas for color application, resulting in a more even finish of the overlying polish. They are especially useful for clients with pronounced longitudinal ridging — a common age-related change in the nail plate. They function as both adhesive base coat and ridge filler." },
  { id: 228, question: "In Texas, an esthetician licensed under TDLR may perform nail services:", question_es: "En Texas, un esteticista licenciado bajo TDLR puede realizar servicios de uñas:", options: ["Yes — the Texas esthetics license scope includes basic nail care services (filing, polishing, basic manicure) in addition to skin care; however, the specific scope should be verified against current Texas Occupations Code Chapter 1603 and TDLR rules, as scope can vary by license classification", "No — nail services require a separate nail technician license in Texas, distinct from the esthetics license", "Only if the esthetician also holds a cosmetology license — esthetics alone does not permit nail services", "Only toenail services — fingernail services require a separate nail license under Texas TDLR rules"], options_es: ["Sí — el alcance de la licencia de estética de Texas incluye servicios básicos de cuidado de uñas (limado, pulido, manicura básica) además del cuidado de la piel; sin embargo, el alcance específico debe verificarse con el Capítulo 1603 actual del Código de Ocupaciones de Texas y las reglas de TDLR, ya que el alcance puede variar según la clasificación de la licencia", "No — los servicios de uñas requieren una licencia separada de técnico en uñas en Texas, distinta de la licencia de estética", "Solo si el esteticista también tiene una licencia de cosmetología — solo la estética no permite los servicios de uñas", "Solo servicios de uñas de los pies — los servicios de uñas de los dedos requieren una licencia separada bajo las reglas de TDLR de Texas"], correct: 0, explanation: "Under Texas Occupations Code Ch. 1603 and TDLR rules, the esthetics license (specialty license) scope includes nail care services in addition to skin care services. The PSI Texas Esthetician exam includes nail care as a tested topic area (Nail Structure & Analysis, Nail Care). Candidates should verify current TDLR rules for any updates to scope of practice." },
  { id: 229, question: "Nail dehydrators used before applying nail enhancements (acrylics, gel) function by:", question_es: "Los deshidratadores de uñas usados antes de aplicar mejoras de uñas (acrílicos, gel) funcionan mediante:", options: ["Removing oils, moisture, and debris from the nail plate surface — this creates a dry, clean surface that allows enhancement products to bond more effectively to the nail plate, improving adhesion and reducing lifting", "Adding moisture to the nail plate to make it flexible and easier to work with during enhancement application", "Chemically etching the nail surface to create microscopic pores for product penetration", "Staining the nail surface to visually identify areas that need additional preparation"], options_es: ["Eliminar aceites, humedad y residuos de la superficie de la placa ungueal — esto crea una superficie seca y limpia que permite que los productos de mejora se unan más efectivamente a la placa ungueal, mejorando la adherencia y reduciendo el levantamiento", "Añadir humedad a la placa ungueal para hacerla flexible y más fácil de trabajar durante la aplicación de mejoras", "Grabado químico de la superficie de la uña para crear poros microscópicos para la penetración del producto", "Teñir la superficie de la uña para identificar visualmente las áreas que necesitan preparación adicional"], correct: 0, explanation: "Nail dehydrators (commonly isopropyl alcohol or acetone-based products) remove surface oil, moisture, and protein residue from the nail plate. This is essential before applying any enhancement product — oils from the nail plate (and from skin contact during service) interfere with adhesion, causing premature lifting. Dehydration is the last preparation step before primer/enhancement application." },
  { id: 230, question: "A French manicure is characterized by:", question_es: "Una manicura francesa se caracteriza por:", options: ["A natural or sheer pink/beige base coat on the nail plate with a clean white polish applied to the free edge — creating a classic, clean look that mimics the appearance of a natural, healthy nail with a well-defined white tip", "A gradient of three different colors blended from the cuticle to the free edge", "Geometric nail art applied only to the ring finger as an accent", "A clear top coat applied over unpolished natural nails"], options_es: ["Un base coat natural o transparente rosado/beige en la placa ungueal con un esmalte blanco limpio aplicado en el borde libre — creando un aspecto clásico y limpio que imita la apariencia de una uña natural y saludable con una punta blanca bien definida", "Un gradiente de tres colores diferentes mezclados desde la cutícula hasta el borde libre", "Arte de uñas geométrico aplicado solo en el dedo anular como acento", "Un top coat transparente aplicado sobre uñas naturales sin pulir"], correct: 0, explanation: "The French manicure (or French polish) consists of: (1) sheer/nude/pale pink base coat over entire nail plate, (2) white or off-white polish applied precisely to the free edge (the 'smile line'), (3) clear or sheer top coat to seal. It creates an elongated, clean look. The 'reverse French' or 'half-moon' is a variation with the half-moon at the cuticle instead of the tip." },
  { id: 231, question: "Nail care services for clients with diabetes require special precautions because:", question_es: "Los servicios de cuidado de uñas para clientes con diabetes requieren precauciones especiales porque:", options: ["Diabetes reduces peripheral circulation and nerve sensation in the hands and feet — clients may not feel pain from injury, wounds heal slowly, and infection risk is elevated; aggressive cuticle cutting, vigorous callus removal, or any break in skin integrity poses a serious risk", "Diabetes causes the nail plate to become chemically different and incompatible with standard polish products", "Diabetic clients must receive nail services only from physicians — esthetics establishments cannot service them", "Diabetes is relevant only for pedicure services — hand manicure services have no special diabetes considerations"], options_es: ["La diabetes reduce la circulación periférica y la sensación nerviosa en las manos y los pies — los clientes pueden no sentir dolor por lesiones, las heridas sanan lentamente y el riesgo de infección es elevado; el corte agresivo de cutículas, la eliminación vigorosa de callos o cualquier ruptura en la integridad de la piel representa un riesgo grave", "La diabetes hace que la placa ungueal sea químicamente diferente e incompatible con los productos de esmalte estándar", "Los clientes diabéticos solo deben recibir servicios de uñas de médicos — los establecimientos de estética no pueden atenderlos", "La diabetes es relevante solo para los servicios de pedicura — los servicios de manicura de manos no tienen consideraciones especiales de diabetes"], correct: 0, explanation: "Diabetes mellitus impairs: (1) peripheral circulation (reduced blood flow to extremities), (2) neuropathy (reduced sensation — client can't feel injury), (3) immune function (increased infection susceptibility), (4) wound healing. Even minor cuts from nippers can develop into serious infections. Protocol: gentle technique only, no aggressive cuticle cutting, report any cuts immediately, and obtain physician clearance if extensive foot work is planned." },
  { id: 232, question: "The correct procedure when a client's skin is accidentally nicked by cuticle nippers during a manicure is:", question_es: "El procedimiento correcto cuando se corta accidentalmente la piel de un cliente con los cortadores de cutícula durante una manicura es:", options: ["Stop the service, apply pressure with a clean gauze pad to stop bleeding, apply styptic powder or antiseptic, put on gloves if not already wearing them, document the incident, and inform the client — only resume the service if bleeding stops and the wound is properly protected", "Apply nail polish over the cut to seal it and continue the service immediately", "Ignore minor nicks — small cuts are a normal, expected part of cuticle care", "Apply a bandage and offer a discount — no other protocol is required for small cuts"], options_es: ["Detener el servicio, aplicar presión con una gasa limpia para detener el sangrado, aplicar polvo estíptico o antiséptico, ponerse guantes si no los está usando ya, documentar el incidente e informar al cliente — solo reanudar el servicio si el sangrado se detiene y la herida está correctamente protegida", "Aplicar esmalte de uñas sobre el corte para sellarlo y continuar el servicio de inmediato", "Ignorar los cortes menores — los pequeños cortes son una parte normal y esperada del cuidado de la cutícula", "Aplicar un vendaje y ofrecer un descuento — no se requiere ningún otro protocolo para los pequeños cortes"], correct: 0, explanation: "A cut during manicure is a bloodborne pathogen exposure event. Required steps: (1) Stop, (2) apply pressure with clean gauze (put on gloves if not already wearing), (3) apply styptic pencil or powder (astringent to stop bleeding), (4) apply antiseptic, (5) cover with bandage if service will continue, (6) document the incident per OSHA exposure control plan requirements." },
  { id: 233, question: "Nail discoloration (yellowing) from prolonged use of dark nail polish can be managed by:", question_es: "La decoloración de las uñas (amarillamiento) por el uso prolongado de esmalte oscuro puede manejarse mediante:", options: ["Consistently using an opaque base coat before applying dark polish (prevents pigment penetration), buffing the surface stain gently with a fine-grit buffer, applying whitening nail treatments, or allowing the stained nail to grow out over time", "Soaking nails in bleach solution weekly — this is the only effective treatment for polish staining", "Applying a color-correcting purple polish to neutralize the yellow stain", "Reducing water intake — staining is caused by internal hydration issues not by polish pigments"], options_es: ["Usar consistentemente un base coat opaco antes de aplicar esmalte oscuro (previene la penetración del pigmento), limar suavemente la mancha superficial con un buffer de grano fino, aplicar tratamientos blanqueadores para uñas o permitir que la uña manchada crezca con el tiempo", "Remojar las uñas en solución de lejía semanalmente — este es el único tratamiento efectivo para el manchado por esmalte", "Aplicar un esmalte púrpura corrector de color para neutralizar la mancha amarilla", "Reducir la ingesta de agua — el manchado es causado por problemas internos de hidratación, no por los pigmentos del esmalte"], correct: 0, explanation: "Dark nail polish (especially red, burgundy, orange shades) can penetrate the nail plate's porous upper layers and cause yellowish staining. Prevention: always use an opaque, pigment-blocking base coat. Treatment for existing stains: fine-grit buffing to remove surface layers of stained keratin, whitening nail scrubs, lemon juice soaks (mild acid), or simply growing out the stained nail plate over several months." },
  { id: 234, question: "The 'dry manicure' technique (performed without soaking the nails in water) offers which advantage over the traditional wet soak method?", question_es: "La técnica de 'manicura en seco' (realizada sin remojar las uñas en agua) ofrece cuál ventaja sobre el método tradicional de remojo húmedo?", options: ["Polish adhesion and longevity are improved because the nail plate is not hydrated/swollen from soaking — a hydrated nail expands during soaking and then contracts as it dries, causing polish to crack and peel sooner; dry-technique nails are better prepared for product adhesion", "The dry technique is faster only — there is no difference in polish longevity between wet and dry techniques", "Soaking is always superior for product adhesion — the wet technique is preferred by all professional nail technicians", "Dry manicure is only appropriate for artificial nail services — natural nails always require soaking"], options_es: ["La adherencia y longevidad del esmalte se mejoran porque la placa ungueal no está hidratada/hinchada por el remojo — una uña hidratada se expande durante el remojo y luego se contrae a medida que se seca, haciendo que el esmalte se agriete y pele antes; las uñas de técnica en seco están mejor preparadas para la adherencia del producto", "La técnica en seco es solo más rápida — no hay diferencia en la longevidad del esmalte entre las técnicas húmeda y seca", "El remojo siempre es superior para la adherencia del producto — la técnica húmeda es preferida por todos los técnicos de uñas profesionales", "La manicura en seco solo es apropiada para los servicios de uñas artificiales — las uñas naturales siempre requieren remojo"], correct: 0, explanation: "The dry (waterless) manicure has become preferred by many professional nail technicians for improved polish longevity. Reason: soaking causes the nail plate's keratin to absorb water, temporarily expanding the nail. As the nail dries after service, it contracts — causing the polish layer (which has already dried) to stress and crack/chip sooner. Dry technique avoids this hydration-dehydration cycle." },
  { id: 235, question: "Nail enhancements (tips, acrylics, or gels) are contraindicated for a client who presents with:", question_es: "Las mejoras de uñas (puntas, acrílicos o geles) están contraindicadas para un cliente que presenta:", options: ["Active nail infection (bacterial paronychia, fungal onychomycosis), onycholysis (nail separation), or significantly compromised nail plates — these conditions are worsened by enhancement application which traps moisture and bacteria beneath the artificial product", "Normal, healthy nails — enhancements are only appropriate for damaged nails that need reinforcement", "Nails shorter than a specific minimum length — short nails cannot receive any enhancements", "A history of wearing nail enhancements in the past — previous enhancement use permanently disqualifies future enhancement services"], options_es: ["Infección activa de uñas (paroniquia bacteriana, onicomicosis fúngica), onicólisis (separación de la uña) o placas ungueales significativamente comprometidas — estas condiciones empeoran con la aplicación de mejoras que atrapan humedad y bacterias debajo del producto artificial", "Uñas normales y saludables — las mejoras solo son apropiadas para uñas dañadas que necesitan refuerzo", "Uñas más cortas que una longitud mínima específica — las uñas cortas no pueden recibir ninguna mejora", "Un historial de uso de mejoras de uñas en el pasado — el uso anterior de mejoras descalifica permanentemente los servicios futuros de mejoras"], correct: 0, explanation: "Nail enhancement contraindications include: active infection (onychomycosis, paronychia — the enhancement traps pathogens beneath it, worsening the infection), onycholysis (space between nail plate and bed becomes infected), and significantly thinned or damaged nail plates. Allergies to acrylic or gel components are also absolute contraindications." },
  { id: 236, question: "Buffing (using a nail buffer) on natural nails should be performed:", question_es: "El pulido (usando un buffer de uñas) en uñas naturales debe realizarse:", options: ["Gently and infrequently — excessive buffing removes nail plate layers and thins the nail over time; buffing is appropriate to smooth ridges and add shine before polish, but repeated aggressive buffing causes irreversible thinning and sensitivity", "As vigorously as possible for maximum shine — intense buffing heat-seals the nail's keratin layers", "Daily — daily buffing keeps nails at optimal health and prevents breakage", "Only on artificial nails — buffing should never be performed on natural nail plates"], options_es: ["Suavemente y con poca frecuencia — el pulido excesivo elimina las capas de la placa ungueal y adelgaza la uña con el tiempo; el pulido es apropiado para alisar las estrías y añadir brillo antes del esmalte, pero el pulido agresivo repetido causa adelgazamiento irreversible y sensibilidad", "Tan vigorosamente como sea posible para el máximo brillo — el calor intenso del pulido sella las capas de queratina de la uña", "Diariamente — el pulido diario mantiene las uñas en una salud óptima y previene la rotura", "Solo en uñas artificiales — el pulido nunca debe realizarse en las placas ungueales naturales"], correct: 0, explanation: "Nail buffing removes the surface layers of the nail plate through abrasion. Benefits: smooths ridges, adds shine, promotes circulation. Risk: over-buffing thins the nail plate, causes heat (from friction), and can create nail sensitivity. Limit buffing to once monthly; use gentle pressure; use fine-grit buffers (240+) on natural nails. Never buff over onycholysis areas." },
  { id: 237, question: "Cuticle nippers used during manicure services must be:", question_es: "Los cortadores de cutícula usados durante los servicios de manicura deben ser:", options: ["Properly cleaned and disinfected using EPA-registered disinfectant after each client — cuticle nippers have hinged joints and cutting edges where blood or tissue can accumulate, making proper disinfection critical; they must be sharp to cut cleanly without tearing", "Replaced with a new pair for every client — cuticle nippers cannot be disinfected and are single-use", "Cleaned only at the end of the workday — between clients a quick wipe with a dry cloth is sufficient", "Sterilized in an autoclave before every use without exception"], options_es: ["Limpiados y desinfectados adecuadamente usando desinfectante registrado por la EPA después de cada cliente — los cortadores de cutícula tienen juntas articuladas y bordes de corte donde puede acumularse sangre o tejido, haciendo crítica la desinfección adecuada; deben estar afilados para cortar limpiamente sin desgarrar", "Reemplazados con un par nuevo para cada cliente — los cortadores de cutícula no pueden desinfectarse y son de uso único", "Limpiados solo al final del día de trabajo — entre clientes una limpieza rápida con un paño seco es suficiente", "Esterilizados en un autoclave antes de cada uso sin excepción"], correct: 0, explanation: "Cuticle nippers are semi-critical implements (contact non-intact skin during cuticle trimming, may occasionally nick skin causing blood contact). Required protocol: after each client, clean (remove all tissue and blood from blades and hinge), then disinfect in EPA-registered hospital-grade disinfectant for full contact time, then rinse, dry, and store in clean container. Sharp nippers make clean cuts — dull ones tear tissue." },
  { id: 238, question: "The purpose of a nail primer used before acrylic or hard gel application is:", question_es: "El propósito de un imprimante de uñas usado antes de la aplicación de acrílico o gel duro es:", options: ["To chemically bond to the nail plate and create a surface that allows the enhancement product to adhere more strongly — acid-based primers etch the nail surface chemically; acid-free primers use hydrogen bonding to create adhesion without the corrosive effect", "To add color and opacity as the first layer of the nail enhancement system", "To remove the nail plate's natural layers in preparation for artificial nail placement", "To prevent onycholysis by sealing the nail plate edges before enhancement application"], options_es: ["Unirse químicamente a la placa ungueal y crear una superficie que permita que el producto de mejora se adhiera con más fuerza — los imprimantes a base de ácido graban la superficie de la uña químicamente; los imprimantes sin ácido usan la unión de hidrógeno para crear adherencia sin el efecto corrosivo", "Añadir color y opacidad como primera capa del sistema de mejora de uñas", "Eliminar las capas naturales de la placa ungueal en preparación para la colocación de uñas artificiales", "Prevenir la onicólisis sellando los bordes de la placa ungueal antes de la aplicación de mejoras"], correct: 0, explanation: "Nail primers improve adhesion between the natural nail and enhancement products. Two types: (1) Acid-based primers (methacrylic acid) — chemically etch the nail surface to create micro-anchor points; very effective but caustic to skin/eyes. (2) Acid-free primers — use van der Waals forces/hydrogen bonding; gentler but require careful application. Both dramatically reduce lifting of enhancements." },
  { id: 239, question: "A nail care service is generally contraindicated for a client with peripheral vascular disease (PVD) because:", question_es: "Un servicio de cuidado de uñas generalmente está contraindicado para un cliente con enfermedad vascular periférica (EVP) porque:", options: ["Poor circulation in the extremities impairs wound healing — any minor cut, abrasion, or pressure from nail services can develop into a non-healing wound or ulcer; aggressive nail care (callus removal, cuticle cutting) should be avoided and medical clearance may be needed", "PVD causes nail polish allergies that prevent safe polish application in all cases", "PVD only affects pedicure services — hand manicures are safe for all PVD clients without modification", "Clients with PVD must receive nail services more frequently to compensate for poor nail growth"], options_es: ["La mala circulación en las extremidades deteriora la cicatrización de heridas — cualquier corte menor, abrasión o presión de los servicios de uñas puede convertirse en una herida no cicatrizante o úlcera; se debe evitar el cuidado agresivo de uñas (eliminación de callos, corte de cutícula) y puede ser necesaria la autorización médica", "La EVP causa alergias al esmalte de uñas que impiden la aplicación segura de esmalte en todos los casos", "La EVP solo afecta los servicios de pedicura — las manicuras de manos son seguras para todos los clientes con EVP sin modificación", "Los clientes con EVP deben recibir servicios de uñas con mayor frecuencia para compensar el crecimiento deficiente de las uñas"], correct: 0, explanation: "PVD reduces blood flow to the extremities, impairing wound healing and immune response. Even minor trauma (nick from nippers, aggressive callus removal) can create a wound that heals poorly or becomes infected. For clients with PVD (or diabetes, which shares these vascular complications), estheticians should use very gentle techniques, avoid any skin breaks, and consider obtaining physician clearance for more involved services." },
  { id: 240, question: "The role of a cuticle oil or cuticle conditioner in nail care is to:", question_es: "El papel de un aceite de cutícula o acondicionador de cutícula en el cuidado de uñas es:", options: ["Moisturize and condition the cuticle skin and proximal nail fold — keeping the cuticle soft and hydrated prevents it from drying, cracking, and tearing (which creates entry points for infection), and helps maintain the protective seal between the nail fold and nail plate", "Dissolve and remove cuticle tissue as an alternative to cuticle nippers", "Act as a base coat substitute — cuticle oil improves polish adhesion directly to the nail plate", "Increase the speed of nail plate growth by feeding the matrix through absorption"], options_es: ["Hidratar y acondicionar la piel de la cutícula y el pliegue ungueal proximal — mantener la cutícula suave e hidratada evita que se seque, agriete y desgarre (lo que crea puntos de entrada para infecciones) y ayuda a mantener el sello protector entre el pliegue ungueal y la placa ungueal", "Disolver y eliminar el tejido de la cutícula como alternativa a los cortadores de cutícula", "Actuar como sustituto del base coat — el aceite de cutícula mejora la adherencia del esmalte directamente a la placa ungueal", "Aumentar la velocidad del crecimiento de la placa ungueal alimentando la matriz a través de la absorción"], correct: 0, explanation: "Cuticle oils (often jojoba, almond, vitamin E, or other plant-based oils) condition the cuticle and surrounding skin. Benefits: prevents dryness and cracking of the cuticle and nail fold skin (cracked cuticles create infection entry points), maintains pliability of the cuticle for comfortable nail services, and keeps the nail fold-to-nail seal intact. Applied after manicure for best results as a finishing step." },
  { id: 241, question: "A gel polish (UV/LED-cured soak-off gel) differs from traditional nail lacquer in that:", question_es: "Un esmalte en gel (gel de remojo curado con UV/LED) difiere del esmalte de uñas tradicional en que:", options: ["Gel polish requires curing under UV or LED light to polymerize and harden — it does not air dry; it is more durable than regular polish (lasting 2–3 weeks without chipping), and requires acetone soak-off removal rather than standard polish remover", "Gel polish dries faster than regular polish when exposed to sunlight — UV exposure for 30 seconds is sufficient", "Gel polish and regular polish are chemically identical — the only difference is the brand marketing", "Gel polish does not require a base or top coat — it is a complete system in one product"], options_es: ["El esmalte en gel requiere curado bajo luz UV o LED para polimerizarse y endurecerse — no se seca al aire; es más duradero que el esmalte regular (dura 2–3 semanas sin astillarse) y requiere remoción con remojo de acetona en lugar del removedor de esmalte estándar", "El esmalte en gel se seca más rápido que el esmalte regular cuando se expone a la luz solar — la exposición UV de 30 segundos es suficiente", "El esmalte en gel y el esmalte regular son químicamente idénticos — la única diferencia es el marketing de la marca", "El esmalte en gel no requiere una base o top coat — es un sistema completo en un solo producto"], correct: 0, explanation: "Gel polish uses photo-initiated polymerization — photoinitiators in the product absorb UV or LED light energy to cross-link polymer chains, hardening the product. This creates a durable, chip-resistant finish lasting 2–4 weeks. Removal requires soaking in acetone (10–15 minutes) to break down the polymer network — mechanical peeling without proper soak-off damages the natural nail plate." },
  { id: 242, question: "When removing gel polish, the correct soak-off technique involves:", question_es: "Al eliminar el esmalte en gel, la técnica correcta de remojo implica:", options: ["Gently buffing the gel surface to break the top seal, soaking cotton in acetone and securing over each nail (foil-wrap method) for 10–15 minutes, then gently sliding off softened gel with an orangewood stick — never forcefully scraping or peeling", "Peeling off the gel by pulling from the free edge — this is the fastest removal method", "Using a power drill (electric file) to completely grind off all gel layers without acetone", "Soaking the entire hand in undiluted acetone for 30 minutes without foil wrapping"], options_es: ["Limar suavemente la superficie del gel para romper el sellado superior, remojar algodón en acetona y asegurarlo sobre cada uña (método de envoltorio de papel de aluminio) durante 10–15 minutos, luego deslizar suavemente el gel suavizado con un palito de naranja — nunca raspar o pelar con fuerza", "Pelar el gel jalándolo desde el borde libre — este es el método de remoción más rápido", "Usar un taladro eléctrico (lima eléctrica) para moler completamente todas las capas de gel sin acetona", "Remojar toda la mano en acetona sin diluir durante 30 minutos sin envoltura de papel de aluminio"], correct: 0, explanation: "Proper gel removal: (1) lightly buff top coat (break the seal), (2) apply acetone-soaked cotton directly over each nail, (3) wrap with foil to hold cotton in contact, (4) wait 10–15 minutes, (5) use light pressure with orangewood stick to slide off softened gel. Forceful peeling or scraping rips off superficial nail plate layers, thinning and damaging the natural nail." },
  { id: 243, question: "The appropriate grit nail file for smoothing and finishing natural nails after shaping is:", question_es: "La lima de uñas de grano apropiado para alisar y terminar uñas naturales después de dar forma es:", options: ["A fine-grit file (180–240 grit or higher) — this removes the micro-tears left by the shaping file, smooths the free edge to prevent snagging, and creates a refined surface without aggressively removing nail plate material", "A coarse 80-grit file — lower grit provides a smoother finish on natural nails", "An extra-fine 400-grit sanding pad is too fine for finishing natural nails — 80-grit is needed", "Any grit is acceptable for natural nail finishing — the buffing block compensates for any roughness"], options_es: ["Una lima de grano fino (180–240 granos o más) — esto elimina los micro-desgarros dejados por la lima de conformado, alisa el borde libre para evitar engancharse y crea una superficie refinada sin eliminar agresivamente el material de la placa ungueal", "Una lima gruesa de 80 granos — el grano más bajo proporciona un acabado más suave en las uñas naturales", "Una almohadilla de lijado extra fina de 400 granos es demasiado fina para terminar las uñas naturales — se necesitan 80 granos", "Cualquier grano es aceptable para el acabado de uñas naturales — el bloque de pulido compensa cualquier rugosidad"], correct: 0, explanation: "After initial shaping with a medium-grit file (150–180), finish the nail edge with a fine-grit file (180–240+). This refines the free edge, removes the microscopic roughness left by the coarser shaping file, and reduces the risk of edge snagging or splitting. Very coarse files (80–100 grit) are for shaping heavy acrylics only — they are far too aggressive for natural nail plates." },
  { id: 244, question: "Nail care services for elderly clients may require modification because:", question_es: "Los servicios de cuidado de uñas para clientes de edad avanzada pueden requerir modificaciones porque:", options: ["Aging nails are often more brittle and ridged (longitudinal ridging increases with age), circulation is reduced, skin is thinner and more fragile, and healing is slower — more gentle techniques, softer products, and modified service protocols are appropriate", "Elderly clients require exactly the same nail care techniques as younger clients — age has no bearing on nail service protocols", "Elderly nails grow faster, requiring more frequent trimming with stronger implements", "Elderly clients cannot receive any nail services due to universal contraindications for their age group"], options_es: ["Las uñas envejecidas suelen ser más quebradizas y estriadas (las estrías longitudinales aumentan con la edad), la circulación está reducida, la piel es más delgada y frágil y la cicatrización es más lenta — son apropiadas técnicas más suaves, productos más suaves y protocolos de servicio modificados", "Los clientes de edad avanzada requieren exactamente las mismas técnicas de cuidado de uñas que los clientes más jóvenes — la edad no tiene ningún efecto en los protocolos de servicio de uñas", "Las uñas de los ancianos crecen más rápido, requiriendo un corte más frecuente con implementos más fuertes", "Los clientes de edad avanzada no pueden recibir ningún servicio de uñas debido a contraindicaciones universales para su grupo de edad"], correct: 0, explanation: "Age-related nail changes: increased longitudinal ridging, nail plate thinning or thickening (variable), slower growth, reduced flexibility, and yellowing. Surrounding skin is thinner, less elastic, and heals more slowly. Adapt technique: use ridge-filling base coats, fine-grit files, extra-gentle cuticle work, nourishing cuticle oils, and avoid aggressive buffing. Be alert for signs of circulation problems or systemic disease." },
  { id: 245, question: "Nail tips applied as a nail extension technique are:", question_es: "Las puntas de uñas aplicadas como técnica de extensión de uñas son:", options: ["Artificial plastic nail extensions that are adhered to the natural nail plate using nail adhesive (nail glue) — they extend the free edge length and serve as a base for applying acrylic, gel, or other overlay products to create the desired nail shape and length", "Decorative nail art decals applied to the surface of polish for design purposes", "The hyponychium region at the underside of the free edge in anatomical nail terminology", "A type of nail file designed specifically for filing the nail tip area"], options_es: ["Extensiones de uñas de plástico artificial que se adhieren a la placa ungueal natural usando adhesivo de uñas (pegamento de uñas) — extienden la longitud del borde libre y sirven como base para aplicar acrílico, gel u otros productos de superposición para crear la forma y longitud de uña deseada", "Calcomanías de arte de uñas decorativas aplicadas a la superficie del esmalte con fines de diseño", "La región del hiponiquio en la parte inferior del borde libre en la terminología ungueal anatómica", "Un tipo de lima de uñas diseñada específicamente para limar el área de la punta de la uña"], correct: 0, explanation: "Nail tips are preformed plastic extensions (typically ABS or similar plastic) that are glued to the free edge of the natural nail using cyanoacrylate (nail glue). They come in various shapes, sizes, and widths. After tip application, the join is blended (filed smooth), and the tip is typically overlaid with acrylic, gel, or another product system to create the full nail enhancement." },
  { id: 246, question: "After a manicure service, proper sanitation of the manicure bowl (finger bowl) used for soaking requires:", question_es: "Después de un servicio de manicura, el saneamiento adecuado del tazón de manicura (tazón para dedos) usado para el remojo requiere:", options: ["Emptying, cleaning with soap and water to remove all organic residue, then disinfecting with EPA-registered disinfectant for the required contact time before refilling for the next client — the bowl contacts client skin and must be disinfected between clients", "Only rinsing with hot water — soap is not needed for manicure bowls", "Replacing the water and adding a few drops of nail polish remover to disinfect the bowl for the next client", "Manicure bowls are non-critical items requiring only a visual inspection between clients — disinfection is needed only weekly"], options_es: ["Vaciar, limpiar con jabón y agua para eliminar todos los residuos orgánicos, luego desinfectar con desinfectante registrado por la EPA durante el tiempo de contacto requerido antes de rellenar para el próximo cliente — el tazón contacta la piel del cliente y debe desinfectarse entre clientes", "Solo enjuagar con agua caliente — el jabón no es necesario para los tazones de manicura", "Reemplazar el agua y añadir unas gotas de removedor de esmalte de uñas para desinfectar el tazón para el próximo cliente", "Los tazones de manicura son artículos no críticos que solo requieren una inspección visual entre clientes — la desinfección solo se necesita semanalmente"], correct: 0, explanation: "Manicure bowls directly contact client skin during soaking — this makes them potentially contaminated with skin cells, body oils, and microorganisms. Between-client protocol: (1) empty (safely dispose of soaking liquid), (2) clean with detergent to remove organic debris, (3) disinfect with EPA-registered disinfectant for full contact time, (4) rinse, dry, and refill for next client." },
  { id: 247, question: "An orangewood stick (wooden pusher) used in nail services is considered:", question_es: "Un palito de naranja (empujador de madera) usado en los servicios de uñas se considera:", options: ["A single-use implement due to its porous wooden material — it cannot be adequately disinfected and must be discarded after one use per client to prevent cross-contamination", "A reusable implement that can be cleaned with soap and water and used for multiple clients", "A disposable item only when it contacts polish — for cuticle pushing it can be sanitized and reused", "A semi-critical implement requiring high-level disinfection between clients"], options_es: ["Un implemento de uso único debido a su material de madera porosa — no puede desinfectarse adecuadamente y debe desecharse después de un uso por cliente para prevenir la contaminación cruzada", "Un implemento reutilizable que puede limpiarse con jabón y agua y usarse para múltiples clientes", "Un artículo desechable solo cuando contacta el esmalte — para empujar la cutícula puede sanearse y reutilizarse", "Un implemento semi-crítico que requiere desinfección de alto nivel entre clientes"], correct: 0, explanation: "Orangewood sticks are made of porous wood, which cannot be adequately disinfected — microorganisms become embedded in the wood's pores beyond the reach of surface disinfectants. They are single-use items that must be discarded after each client service. Similarly, all wooden implements (wax applicators, wooden pushers) are single-use. Metal nail pushers can be disinfected and reused." },
  { id: 248, question: "A nail buff (buffer) block provides which final step benefit in a manicure?", question_es: "Un bloque buffer de uñas proporciona cuál beneficio de paso final en una manicura?", options: ["When used with the fine-grit side, it smooths and shines the nail plate surface to a natural gloss — this can replace polish for clients who prefer a natural look, or prepare the nail plate to better accept base coat and polish by creating a smooth, even surface", "Removes all nail polish from the nail surface without chemical remover when used aggressively", "Applies topcoat evenly across the nail surface through friction-based product transfer", "Trims and shapes the free edge of the nail — it replaces the nail file for shaping"], options_es: ["Cuando se usa con el lado de grano fino, alisa y da brillo a la superficie de la placa ungueal a un brillo natural — esto puede reemplazar el esmalte para los clientes que prefieren un look natural, o preparar la placa ungueal para aceptar mejor el base coat y el esmalte creando una superficie suave y uniforme", "Elimina todo el esmalte de uñas de la superficie de la uña sin removedor químico cuando se usa agresivamente", "Aplica el top coat uniformly en la superficie de la uña a través de la transferencia de producto basada en fricción", "Recorta y da forma al borde libre de la uña — reemplaza la lima de uñas para dar forma"], correct: 0, explanation: "A multi-sided nail buffer typically has: coarse side (smooth ridges), medium side (refine surface), fine side (add shine). The fine/shine side creates a mirror-like natural nail gloss through gentle friction that compresses and smooths the nail plate's surface keratin layers. This shining effect lasts 1–2 weeks. Over-buffing removes nail plate thickness — use sparingly." },
  { id: 249, question: "The appropriate response when a client requests a nail service but their nails show signs consistent with onychomycosis (thickened, yellowed, crumbling nail plate) is:", question_es: "La respuesta apropiada cuando un cliente solicita un servicio de uñas pero sus uñas muestran signos consistentes con la onicomicosis (placa ungueal engrosada, amarillenta y desmoronada) es:", options: ["Decline service on the affected nail(s) and refer the client to a physician for diagnosis and treatment — fungal nail infections are contagious, treatment is beyond esthetics scope, and enhancement application over suspected onychomycosis is never appropriate", "Apply a thick layer of antifungal polish to treat the infection during the service", "Proceed with full nail service including enhancement application — onychomycosis is not a contraindication for esthetics services", "File the affected nail aggressively to remove infected tissue and create a healthy nail surface for polishing"], options_es: ["Rechazar el servicio en la(s) uña(s) afectada(s) y derivar al cliente a un médico para diagnóstico y tratamiento — las infecciones fúngicas de las uñas son contagiosas, el tratamiento está más allá del alcance de la estética y la aplicación de mejoras sobre la onicomicosis sospechada nunca es apropiada", "Aplicar una capa gruesa de esmalte antimicótico para tratar la infección durante el servicio", "Proceder con el servicio completo de uñas incluyendo la aplicación de mejoras — la onicomicosis no es una contraindicación para los servicios de estética", "Limar la uña afectada agresivamente para eliminar el tejido infectado y crear una superficie de uña saludable para pulir"], correct: 0, explanation: "Suspected onychomycosis requires: (1) declining service on affected nails (the infection is contagious — filing/buffing creates infectious debris), (2) medical referral for diagnosis (confirmation requires microscopy or culture — estheticians cannot definitively diagnose) and treatment (prescription oral or topical antifungals). Never apply enhancement products over suspected fungal nails — this creates the ideal warm, moist environment for fungal proliferation." },
  { id: 250, question: "Styptic powder or alum used during nail services is applied to:", question_es: "El polvo estíptico o alumbre usado durante los servicios de uñas se aplica para:", options: ["Stop minor bleeding from small cuts or nicks to the cuticle or surrounding skin — the powder acts as an astringent that causes blood vessel constriction (hemostasis) to stop capillary bleeding quickly; the area should then be cleaned with antiseptic", "Soften hardened cuticle tissue before cuticle removal procedures", "Disinfect the nail plate surface before polish application", "Remove nail plate staining from dark-colored polishes"], options_es: ["Detener el sangrado menor de pequeños cortes o rasguños en la cutícula o la piel circundante — el polvo actúa como astringente que causa la constricción de los vasos sanguíneos (hemostasia) para detener el sangrado capilar rápidamente; el área debe limpiarse luego con antiséptico", "Suavizar el tejido de la cutícula endurecida antes de los procedimientos de remoción de cutícula", "Desinfectar la superficie de la placa ungueal antes de la aplicación del esmalte", "Eliminar el manchado de la placa ungueal de los esmaltes de colores oscuros"], correct: 0, explanation: "Styptic products (styptic pencil, powder, or liquid) contain alum (potassium aluminum sulfate) or ferric subsulfate — astringents that cause blood vessel constriction to stop minor capillary bleeding from small cuts. Standard use in nail services: apply a small amount of styptic to the nicked area with a clean cotton swab, press briefly, then clean the area with antiseptic before continuing the service." },
]

